import * as arc from "open-arc";

export type ParseFn = (phrase: string) => string;

export const parseSpec = arc.defineRegion<ParseFn>({
  "id": "acronym.parse",
  "intent": [
    "Exercise \"acronym\": implement `parse`.",
    "Convert a phrase to its acronym.",
    "Techies love their TLA (Three Letter Acronyms)!",
    "Help generate some jargon by writing a program that converts a long name like Portable Network Graphics to its acronym (PNG).",
    "Punctuation is handled as follows: hyphens are word separators (like whitespace); all other punctuation can be removed from the input.",
    "For example:",
    "| Input                     | Output | | ------------------------- | ------ | | As Soon As Possible       | ASAP   | | Liquid-crystal display    | LCD    | | Thank George It's Friday! | TGIF   |"
  ],
  "examples": [
    {
      "name": "Acronym are produced from > title cased phrases",
      "args": [
        "Portable Network Graphics"
      ],
      "expected": "PNG"
    },
    {
      "name": "Acronym are produced from > other title cased phrases",
      "args": [
        "Ruby on Rails"
      ],
      "expected": "ROR"
    },
    {
      "name": "Acronym are produced from > inconsistently cased phrases",
      "args": [
        "HyperText Markup Language"
      ],
      "expected": "HTML"
    }
  ]
});

// @openarc:begin acronym.parse
export const parse: ParseFn = (phrase) => arc.todo("acronym.parse");
// @openarc:end acronym.parse

export function parse(phrase: string): string {
  const words = phrase.split(/[\s-]+/);
  const acronym = words.map(word => word[0].toUpperCase()).join('');
  return acronym;
}

import * as arc from "open-arc";

export type ConvertFn = (digits: number[], inputBase: number, outputBase: number) => number[];

export const convertSpec = arc.defineRegion<ConvertFn>({
  "id": "allYourBase.convert",
  "intent": [
    "Exercise \"all-your-base\": implement `convert`.",
    "Convert a sequence of digits in one base, representing a number, into a sequence of digits in another base, representing the same number.",
    "~~~~exercism/note Try to implement the conversion yourself. Do not use something else to perform the conversion for you. ~~~~",
    "## About [Positional Notation][positional-notation]",
    "In positional notation, a number in base **b** can be understood as a linear combination of powers of **b**.",
    "The number 42, _in base 10_, means:",
    "`(4 × 10¹) + (2 × 10⁰)`",
    "The number 101010, _in base 2_, means:",
    "`(1 × 2⁵) + (0 × 2⁴) + (1 × 2³) + (0 × 2²) + (1 × 2¹) + (0 × 2⁰)`",
    "The number 1120, _in base 3_, means:",
    "`(1 × 3³) + (1 × 3²) + (2 × 3¹) + (0 × 3⁰)`",
    "_Yes. Those three numbers above are exactly the same. Congratulations!_",
    "[positional-notation]: https://en.wikipedia.org/wiki/Positional_notation"
  ],
  "examples": [
    {
      "name": "Converter > single bit one to decimal",
      "args": [
        [
          1
        ],
        2,
        10
      ],
      "expected": [
        1
      ]
    },
    {
      "name": "Converter > binary to single decimal",
      "args": [
        [
          1,
          0,
          1
        ],
        2,
        10
      ],
      "expected": [
        5
      ]
    },
    {
      "name": "Converter > single decimal to binary",
      "args": [
        [
          5
        ],
        10,
        2
      ],
      "expected": [
        1,
        0,
        1
      ]
    }
  ]
});

// @openarc:begin allYourBase.convert
export const convert: ConvertFn = (digits, inputBase, outputBase) => {
  let decimal = 0;
  for (let i = 0; i < digits.length; i++) {
      decimal += digits[i] * Math.pow(inputBase, digits.length - i - 1);
    }
  const result: number[] = [];
  while (decimal > 0) {
      result.unshift(decimal % outputBase);
      decimal = Math.floor(decimal / outputBase);
    }
  return result.length > 0 ? result : [0];
};
// @openarc:end allYourBase.convert

export function convert(digits: number[], inputBase: number, outputBase: number): number[] {
  if (inputBase < 2 || inputBase > 36 || outputBase < 2 || outputBase > 36) {
    return [];
  }

  let decimalValue = 0;
  for (const digit of digits) {
    if (digit < 0 || digit >= inputBase) {
      return [];
    }
    decimalValue = decimalValue * inputBase + digit;
  }

  if (decimalValue === 0) {
    return [0];
  }

  const result: number[] = [];
  while (decimalValue > 0) {
    result.unshift(decimalValue % outputBase);
    decimalValue = Math.floor(decimalValue / outputBase);
  }

  return result;
}

import * as arc from "open-arc";

export type FindFn = (haystack: number[], needle: number) => number;

export const findSpec = arc.defineRegion<FindFn>({
  "id": "binarySearch.find",
  "intent": [
    "Exercise \"binary-search\": implement `find`.",
    "Your task is to implement a binary search algorithm.",
    "A binary search algorithm finds an item in a list by repeatedly splitting it in half, only keeping the half which contains the item we're looking for. It allows us to quickly narrow down the possible locations of our item until we find it, or until we've eliminated all possible locations.",
    "~~~~exercism/caution Binary search only works when a list has been sorted. ~~~~",
    "The algorithm looks like this:",
    "- Find the middle element of a _sorted_ list and compare it with the item we're looking for. - If the middle element is our item, then we're done! - If the middle element is greater than our item, we can eliminate that element and all the elements **after** it. - If the middle element is less than our item, we can eliminate that element and all the elements **before** it. - If every element of the list has been eliminated then the item is not in the list. - Otherwise, repeat the process on the part of the list that has not been eliminated.",
    "Here's an example:",
    "Let's say we're looking for the number 23 in the following sorted list: `[4, 8, 12, 16, 23, 28, 32]`.",
    "- We start by comparing 23 with the middle element, 16. - Since 23 is greater than 16, we can eliminate the left half of the list, leaving us with `[23, 28, 32]`. - We then compare 23 with the new middle element, 28. - Since 23 is less than 28, we can eliminate the right half of the list: `[23]`. - We've found our item."
  ],
  "examples": [
    {
      "name": "Binary Search > finds a value in an array with one element",
      "args": [
        [
          6
        ],
        6
      ],
      "expected": 0
    },
    {
      "name": "Binary Search > finds a value in the middle of an array",
      "args": [
        [
          1,
          3,
          4,
          6,
          8,
          9,
          11
        ],
        6
      ],
      "expected": 3
    },
    {
      "name": "Binary Search > finds a value at the beginning of an array",
      "args": [
        [
          1,
          3,
          4,
          6,
          8,
          9,
          11
        ],
        1
      ],
      "expected": 0
    }
  ]
});

// @openarc:begin binarySearch.find
export const find: FindFn = (haystack, needle) => {
  let left = 0;
  let right = haystack.length - 1;
  while (left <= right) {
      const mid = Math.floor((left + right) / 2);
      if (haystack[mid] === needle) {
        return mid;
      } else if (haystack[mid] < needle) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
  return -1;
};
// @openarc:end binarySearch.find

export function find(haystack: number[], needle: number): number {
  let left = 0;
  let right = haystack.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    const midValue = haystack[mid];

    if (midValue === needle) {
      return mid;
    } else if (midValue < needle) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return -1; // Return -1 if the item is not found
}

import * as arc from "open-arc";

export type MakeDiamondFn = (character: string) => string;

export const makeDiamondSpec = arc.defineRegion<MakeDiamondFn>({
  "id": "diamond.makeDiamond",
  "intent": [
    "Exercise \"diamond\": implement `makeDiamond`.",
    "The diamond kata takes as its input a letter, and outputs it in a diamond shape. Given a letter, it prints a diamond starting with 'A', with the supplied letter at the widest point.",
    "## Requirements",
    "- The first row contains one 'A'. - The last row contains one 'A'. - All rows, except the first and last, have exactly two identical letters. - All rows have as many trailing spaces as leading spaces. (This might be 0). - The diamond is horizontally symmetric. - The diamond is vertically symmetric. - The diamond has a square shape (width equals height). - The letters form a diamond shape. - The top half has the letters in ascending order. - The bottom half has the letters in descending order. - The four corners (containing the spaces) are triangles.",
    "## Examples",
    "In the following examples, spaces are indicated by `·` characters.",
    "Diamond for letter 'A':",
    "```text A ```",
    "Diamond for letter 'C':",
    "```text ··A·· ·B·B· C···C ·B·B· ··A·· ```",
    "Diamond for letter 'E':",
    "```text ····A···· ···B·B··· ··C···C·· ·D·····D· E·······E ·D·····D· ··C···C·· ···B·B··· ····A···· ```"
  ],
  "examples": [
    {
      "name": "Make diamond function > test letter A",
      "args": [
        "A"
      ],
      "expected": "A\n"
    }
  ]
});

// @openarc:begin diamond.makeDiamond
export const makeDiamond: MakeDiamondFn = (character) => {
  const n = character.charCodeAt(0) - 'A'.charCodeAt(0);
  let diamond = '';
  for (let i = 0; i <= n; i++) {
      const spaces = ' '.repeat(n - i);
      const letters = i === 0 ? 'A' : 'A' + 'B'.repeat(i) + 'A';
      diamond += spaces + letters + spaces + '\n';
    }
  for (let i = n - 1; i >= 0; i--) {
      const spaces = ' '.repeat(n - i);
      const letters = i === 0 ? 'A' : 'A' + 'B'.repeat(i) + 'A';
      diamond += spaces + letters + spaces + '\n';
    }
  return diamond;
};
// @openarc:end diamond.makeDiamond

export function makeDiamond(character: string): string {
  if (character.length !== 1 || !character.match(/[A-Z]/)) {
    throw new Error("Input must be a single uppercase letter");
  }

  const n = character.charCodeAt(0) - 'A'.charCodeAt(0);
  const diamond: string[] = [];

  for (let i = 0; i <= n; i++) {
    const spaces = ' '.repeat(n - i);
    const letter = String.fromCharCode('A'.charCodeAt(0) + i);
    diamond.push(spaces + letter + spaces.repeat(2 * i) + letter);
  }

  for (let i = n - 1; i >= 0; i--) {
    diamond.push(diamond[i]);
  }

  return diamond.join('\n');
}

import * as arc from "open-arc";

export interface Nested extends Array<number | null | undefined | Nested> {}

export type FlattenFn = (input: Nested) => number[];

export const flattenSpec = arc.defineRegion<FlattenFn>({
  "id": "flattenArray.flatten",
  "intent": [
    "Exercise \"flatten-array\": implement `flatten`.",
    "Take a nested array of any depth and return a fully flattened array.",
    "Note that some language tracks may include null-like values in the input array, and the way these values are represented varies by track. Such values should be excluded from the flattened array.",
    "Additionally, the input may be of a different data type and contain different types, depending on the track.",
    "Check the test suite for details.",
    "## Example",
    "input: `[1, [2, 6, null], [[null, [4]], 5]]`",
    "output: `[1, 2, 6, 4, 5]`"
  ],
  "examples": [
    {
      "name": "Flatten Array > no nesting",
      "args": [
        [
          0,
          1,
          2
        ]
      ],
      "expected": [
        0,
        1,
        2
      ]
    },
    {
      "name": "Flatten Array > flattens array with just integers present",
      "args": [
        [
          1,
          [
            2,
            3,
            4,
            5,
            6,
            7
          ],
          8
        ]
      ],
      "expected": [
        1,
        2,
        3,
        4,
        5,
        6,
        7,
        8
      ]
    },
    {
      "name": "Flatten Array > 5 level nesting",
      "args": [
        [
          0,
          2,
          [
            [
              2,
              3
            ],
            8,
            100,
            4,
            [
              [
                [
                  50
                ]
              ]
            ]
          ],
          -2
        ]
      ],
      "expected": [
        0,
        2,
        2,
        3,
        8,
        100,
        4,
        50,
        -2
      ]
    }
  ]
});

// @openarc:begin flattenArray.flatten
export const flatten: FlattenFn = (input) => {
  const result: number[] = [];
  const stack: (number | null | undefined | Nested)[] = [...input];
  while (stack.length > 0) {
      const current = stack.pop();
      if (Array.isArray(current)) {
        stack.push(...current);
      } else if (current !== null && current !== undefined) {
        result.push(current);
      }
    }
  return result.reverse();
};
// @openarc:end flattenArray.flatten

export interface Nested extends Array<number | null | undefined | Nested> {}

export function flatten(input: Nested): number[] {
  const result: number[] = [];

  function flattenHelper(arr: Nested) {
    for (const item of arr) {
      if (Array.isArray(item)) {
        flattenHelper(item);
      } else if (item !== null && item !== undefined) {
        result.push(item);
      }
    }
  }

  flattenHelper(input);
  return result;
}

