// @openarc:begin foodChain.verses
export const verses: VersesFn = (start, end) => arc.todo("foodChain.verses");
// @openarc:end foodChain.verses

const animals = [
  "fly",
  "spider",
  "bird",
  "cat",
  "dog",
  "goat",
  "cow",
  "horse"
];

const actions = [
  "",
  "It wriggled and jiggled and tickled inside her.",
  "How absurd to swallow a bird!",
  "Imagine that, to swallow a cat!",
  "What a hog, to swallow a dog!",
  "Just opened her throat and swallowed a goat!",
  "I don't know how she swallowed a cow!",
  "She's dead, of course!"
];

export function verse(n: number): string {
  if (n < 1 || n > animals.length) {
    throw new Error("Invalid verse number");
  }

  let result = `I know an old lady who swallowed a ${animals[n - 1]}.\n`;
  result += actions[n - 1] + "\n";

  for (let i = n - 1; i > 0; i--) {
    result += `She swallowed the ${animals[i]} to catch the ${animals[i - 1]}`;
    if (i > 1) {
      result += ` that ${actions[i - 1]}`;
    }
    result += ".\n";
  }

  result += "I don't know why she swallowed the fly. Perhaps she'll die.\n";
  return result;
}

export function verses(start: number, end: number): string {
  if (start < 1 || end > animals.length || start > end) {
    throw new Error("Invalid verse range");
  }

  let result = "";
  for (let i = start; i <= end; i++) {
    result += verse(i);
    if (i < end) {
      result += "\n";
    }
  }
  return result;
}

import * as arc from "open-arc";

export type IsPairedFn = (input: string) => boolean;

export const isPairedSpec = arc.defineRegion<IsPairedFn>({
  "id": "matchingBrackets.isPaired",
  "intent": [
    "Exercise \"matching-brackets\": implement `isPaired`.",
    "Given a string containing brackets `[]`, braces `{}`, parentheses `()`, or any combination thereof, verify that any and all pairs are matched and nested correctly. Any other characters should be ignored. For example, `\"{what is (42)}?\"` is balanced and `\"[text}\"` is not."
  ],
  "examples": [
    {
      "name": "Matching Brackets > paired square brackets",
      "args": [
        "[]"
      ],
      "expected": true
    },
    {
      "name": "Matching Brackets > empty string",
      "args": [
        ""
      ],
      "expected": true
    },
    {
      "name": "Matching Brackets > unpaired brackets",
      "args": [
        "[["
      ],
      "expected": false
    }
  ]
});

// @openarc:begin matchingBrackets.isPaired
export const isPaired: IsPairedFn = (input) => {
  const stack: string[] = [];
  const pairs: { [key: string]: string } = {
      ']': '[',
      '}': '{',
      ')': '('
    };
  for (const char of input) {
      if (char === '[' || char === '{' || char === '(') {
        stack.push(char);
      } else if (char === ']' || char === '}' || char === ')') {
        if (stack.length === 0 || stack.pop() !== pairs[char]) {
          return false;
        }
      }
    }
  return stack.length === 0;
};
// @openarc:end matchingBrackets.isPaired

export function isPaired(input: string): boolean {
  const stack: string[] = [];
  const pairs: { [key: string]: string } = {
    ')': '(',
    '}': '{',
    ']': '['
  };

  for (const char of input) {
    if (char === '(' || char === '{' || char === '[') {
      stack.push(char);
    } else if (char === ')' || char === '}' || char === ']') {
      if (stack.length === 0 || stack.pop() !== pairs[char]) {
        return false;
      }
    }
  }

  return stack.length === 0;
}

