import * as arc from "open-arc";

export type EncodeFn = (numbers: number[]) => number[];

export const encodeSpec = arc.defineRegion<EncodeFn>({
  "id": "variableLengthQuantity.encode",
  "intent": [
    "Exercise \"variable-length-quantity\": implement `encode`.",
    "Implement variable length quantity encoding and decoding.",
    "The goal of this exercise is to implement [VLQ][vlq] encoding/decoding.",
    "In short, the goal of this encoding is to encode integer values in a way that would save bytes. Only the first 7 bits of each byte are significant (right-justified; sort of like an ASCII byte). So, if you have a 32-bit value, you have to unpack it into a series of 7-bit bytes. Of course, you will have a variable number of bytes depending upon your integer. To indicate which is the last byte of the series, you leave bit #7 clear. In all of the preceding bytes, you set bit #7.",
    "So, if an integer is between `0-127`, it can be represented as one byte. Although VLQ can deal with numbers of arbitrary sizes, for this exercise we will restrict ourselves to only numbers that fit in a 32-bit unsigned integer. Here are examples of integers as 32-bit values, and the variable length quantities that they translate to:",
    "```text NUMBER        VARIABLE QUANTITY 00000000              00 00000040              40 0000007F              7F 00000080             81 00 00002000             C0 00 00003FFF             FF 7F 00004000           81 80 00 00100000           C0 80 00 001FFFFF           FF FF 7F 00200000          81 80 80 00 08000000          C0 80 80 00 0FFFFFFF          FF FF FF 7F ```",
    "[vlq]: https://en.wikipedia.org/wiki/Variable-length_quantity"
  ],
  "examples": [
    {
      "name": "VariableLengthQuantity > Encode a series of integers, producing a series of bytes. > zero",
      "args": [
        [
          0
        ]
      ],
      "expected": [
        0
      ]
    },
    {
      "name": "VariableLengthQuantity > Encode a series of integers, producing a series of bytes. > arbitrary single byte",
      "args": [
        [
          64
        ]
      ],
      "expected": [
        64
      ]
    },
    {
      "name": "VariableLengthQuantity > Encode a series of integers, producing a series of bytes. > largest single byte",
      "args": [
        [
          127
        ]
      ],
      "expected": [
        127
      ]
    }
  ]
});

// @openarc:begin variableLengthQuantity.encode
export const encode: EncodeFn = (numbers) => {
  const result: number[] = [];
  for (const num of numbers) {
      let remaining = num;
      while (remaining >= 128) {
        result.push((remaining & 127) | 128);
        remaining >>= 7;
      }
      result.push(remaining);
    }
  return result;
};
// @openarc:end variableLengthQuantity.encode

export type DecodeFn = (bytes: number[]) => number[];

export const decodeSpec = arc.defineRegion<DecodeFn>({
  "id": "variableLengthQuantity.decode",
  "intent": [
    "Exercise \"variable-length-quantity\": implement `decode`.",
    "Implement variable length quantity encoding and decoding.",
    "The goal of this exercise is to implement [VLQ][vlq] encoding/decoding.",
    "In short, the goal of this encoding is to encode integer values in a way that would save bytes. Only the first 7 bits of each byte are significant (right-justified; sort of like an ASCII byte). So, if you have a 32-bit value, you have to unpack it into a series of 7-bit bytes. Of course, you will have a variable number of bytes depending upon your integer. To indicate which is the last byte of the series, you leave bit #7 clear. In all of the preceding bytes, you set bit #7.",
    "So, if an integer is between `0-127`, it can be represented as one byte. Although VLQ can deal with numbers of arbitrary sizes, for this exercise we will restrict ourselves to only numbers that fit in a 32-bit unsigned integer. Here are examples of integers as 32-bit values, and the variable length quantities that they translate to:",
    "```text NUMBER        VARIABLE QUANTITY 00000000              00 00000040              40 0000007F              7F 00000080             81 00 00002000             C0 00 00003FFF             FF 7F 00004000           81 80 00 00100000           C0 80 00 001FFFFF           FF FF 7F 00200000          81 80 80 00 08000000          C0 80 80 00 0FFFFFFF          FF FF FF 7F ```",
    "[vlq]: https://en.wikipedia.org/wiki/Variable-length_quantity"
  ],
  "examples": [
    {
      "name": "VariableLengthQuantity > Decode a series of bytes, producing a series of integers. > one byte",
      "args": [
        [
          127
        ]
      ],
      "expected": [
        127
      ]
    },
    {
      "name": "VariableLengthQuantity > Decode a series of bytes, producing a series of integers. > two bytes",
      "args": [
        [
          192,
          0
        ]
      ],
      "expected": [
        8192
      ]
    },
    {
      "name": "VariableLengthQuantity > Decode a series of bytes, producing a series of integers. > three bytes",
      "args": [
        [
          255,
          255,
          127
        ]
      ],
      "expected": [
        2097151
      ]
    }
  ]
});

// @openarc:begin variableLengthQuantity.decode
export const decode: DecodeFn = (bytes) => {
  const result: number[] = [];
  let current = 0;
  for (const byte of bytes) {
      current = (current << 7) | (byte & 127);
      if (byte < 128) {
        result.push(current);
        current = 0;
      }
    }
  return result;
};
// @openarc:end variableLengthQuantity.decode

export function encode(numbers: number[]): number[] {
  const encoded: number[] = [];
  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Number out of range for 32-bit unsigned integer");
    }
    let remaining = num;
    let first = true;
    while (remaining > 0) {
      const byte = remaining & 0x7F;
      remaining >>= 7;
      if (!first) {
        byte |= 0x80;
      }
      encoded.push(byte);
      first = false;
    }
  }
  return encoded;
}

export function decode(bytes: number[]): number[] {
  const decoded: number[] = [];
  let num = 0;
  for (const byte of bytes) {
    num = (num << 7) | (byte & 0x7F);
    if ((byte & 0x80) === 0) {
      decoded.push(num);
      num = 0;
    }
  }
  return decoded;
}

