export function parse(phrase: string): string {
  const words = phrase.split(/[\s-]+/);
  const acronym = words.map(word => word[0].toUpperCase()).join('');
  return acronym;
}

import * as arc from "open-arc";

export type ConvertFn = (digits: number[], inputBase: number, outputBase: number) => number[];

export const convertSpec = arc.defineRegion<ConvertFn>({
  "id": "allYourBase.convert",
  "intent": [
    "Exercise \"all-your-base\": implement `convert`.",
    "Convert a sequence of digits in one base, representing a number, into a sequence of digits in another base, representing the same number.",
    "~~~~exercism/note Try to implement the conversion yourself. Do not use something else to perform the conversion for you. ~~~~",
    "## About [Positional Notation][positional-notation]",
    "In positional notation, a number in base **b** can be understood as a linear combination of powers of **b**.",
    "The number 42, _in base 10_, means:",
    "`(4 × 10¹) + (2 × 10⁰)`",
    "The number 101010, _in base 2_, means:",
    "`(1 × 2⁵) + (0 × 2⁴) + (1 × 2³) + (0 × 2²) + (1 × 2¹) + (0 × 2⁰)`",
    "The number 1120, _in base 3_, means:",
    "`(1 × 3³) + (1 × 3²) + (2 × 3¹) + (0 × 3⁰)`",
    "_Yes. Those three numbers above are exactly the same. Congratulations!_",
    "[positional-notation]: https://en.wikipedia.org/wiki/Positional_notation"
  ],
  "examples": [
    {
      "name": "Converter > single bit one to decimal",
      "args": [
        [
          1
        ],
        2,
        10
      ],
      "expected": [
        1
      ]
    },
    {
      "name": "Converter > binary to single decimal",
      "args": [
        [
          1,
          0,
          1
        ],
        2,
        10
      ],
      "expected": [
        5
      ]
    },
    {
      "name": "Converter > single decimal to binary",
      "args": [
        [
          5
        ],
        10,
        2
      ],
      "expected": [
        1,
        0,
        1
      ]
    }
  ]
});

// @openarc:begin allYourBase.convert
export const convert: ConvertFn = (digits, inputBase, outputBase) => {
  let decimal = 0;
  for (let i = 0; i < digits.length; i++) {
      decimal += digits[i] * Math.pow(inputBase, digits.length - i - 1);
    }
  const result: number[] = [];
  while (decimal > 0) {
      result.unshift(decimal % outputBase);
      decimal = Math.floor(decimal / outputBase);
    }
  return result.length > 0 ? result : [0];
};
// @openarc:end allYourBase.convert

export function convert(digits: number[], inputBase: number, outputBase: number): number[] {
  if (inputBase < 2 || inputBase > 36 || outputBase < 2 || outputBase > 36) {
    return [];
  }

  let decimalValue = 0;
  for (const digit of digits) {
    if (digit < 0 || digit >= inputBase) {
      return [];
    }
    decimalValue = decimalValue * inputBase + digit;
  }

  if (decimalValue === 0) {
    return [0];
  }

  const result: number[] = [];
  while (decimalValue > 0) {
    result.unshift(decimalValue % outputBase);
    decimalValue = Math.floor(decimalValue / outputBase);
  }

  return result;
}

