// @openarc:begin spiralMatrix.ofSize
export const ofSize: OfSizeFn = (size) => {
  if (size === 0) return [];
  const matrix = Array.from({ length: size }, () => Array(size).fill(0));
  let num = 1;
  let top = 0, bottom = size - 1, left = 0, right = size - 1;
  while (top <= bottom && left <= right) {
      for (let i = left; i <= right; i++) matrix[top][i] = num++;
      top++;
      for (let i = top; i <= bottom; i++) matrix[i][right] = num++;
      right--;
      for (let i = right; i >= left; i--) matrix[bottom][i] = num++;
      bottom--;
      for (let i = bottom; i >= top; i--) matrix[i][left] = num++;
      left++;
    }
  return matrix;
};
// @openarc:end spiralMatrix.ofSize

export function ofSize(size: number): number[][] {
  if (size <= 0) return [];

  const matrix: number[][] = Array.from({ length: size }, () => Array(size).fill(0));
  let num = 1;
  let top = 0, bottom = size - 1, left = 0, right = size - 1;

  while (top <= bottom && left <= right) {
    for (let i = left; i <= right; i++) {
      matrix[top][i] = num++;
    }
    top++;

    for (let i = top; i <= bottom; i++) {
      matrix[i][right] = num++;
    }
    right--;

    if (top <= bottom) {
      for (let i = right; i >= left; i--) {
        matrix[bottom][i] = num++;
      }
      bottom--;
    }

    if (left <= right) {
      for (let i = bottom; i >= top; i--) {
        matrix[i][left] = num++;
      }
      left++;
    }
  }

  return matrix;
}

