// @openarc:begin variableLengthQuantity.encode
export const encode: EncodeFn = (numbers) => {
  const result: number[] = [];
  for (const num of numbers) {
      let remaining = num;
      while (remaining >= 128) {
        result.push((remaining & 127) | 128);
        remaining >>= 7;
      }
      result.push(remaining);
    }
  return result;
};
