// @openarc:begin binarySearch.find
export const find: FindFn = (haystack, needle) => {
  let left = 0;
  let right = haystack.length - 1;
  while (left <= right) {
      const mid = Math.floor((left + right) / 2);
      if (haystack[mid] === needle) {
        return mid;
      } else if (haystack[mid] < needle) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
  return -1;
};
// @openarc:end binarySearch.find

export function find(haystack: number[], needle: number): number {
  let left = 0;
  let right = haystack.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    const midValue = haystack[mid];

    if (midValue === needle) {
      return mid;
    } else if (midValue < needle) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return -1; // Return -1 if the item is not found
}

