// @openarc:begin flattenArray.flatten
export const flatten: FlattenFn = (input) => {
  const result: number[] = [];
  const stack: (number | null | undefined | Nested)[] = [...input];
  while (stack.length > 0) {
      const current = stack.pop();
      if (Array.isArray(current)) {
        stack.push(...current);
      } else if (current !== null && current !== undefined) {
        result.push(current);
      }
    }
  return result.reverse();
};
// @openarc:end flattenArray.flatten

export interface Nested extends Array<number | null | undefined | Nested> {}

export function flatten(input: Nested): number[] {
  const result: number[] = [];

  function flattenHelper(arr: Nested) {
    for (const item of arr) {
      if (Array.isArray(item)) {
        flattenHelper(item);
      } else if (item !== null && item !== undefined) {
        result.push(item);
      }
    }
  }

  flattenHelper(input);
  return result;
}

