export function translate(phrase: string): string {
  const words = phrase.split(' ');
  const translatedWords = words.map(word => {
    if (/^[aeiou]|xr|yt/.test(word)) {
      return word + 'ay';
    } else if (/qu/.test(word)) {
      const match = word.match(/(.*?qu)(.*)/);
      if (match) {
        return match[2] + match[1] + 'ay';
      }
    } else if (/y/.test(word)) {
      const match = word.match(/(.*?y)(.*)/);
      if (match) {
        return match[2] + match[1] + 'ay';
      }
    } else {
      const match = word.match(/(.*?)([bcdfghjklmnpqrstvwxyz]+)/);
      if (match) {
        return match[2] + match[1] + 'ay';
      }
    }
    return word;
  });
  return translatedWords.join(' ');
}

