export function count(rows: string[]): number {
  if (rows.length === 0 || rows[0].length === 0) return 0;

  const height = rows.length;
  const width = rows[0].length;
  let count = 0;

  for (let i = 0; i < height - 1; i++) {
    for (let j = 0; j < width - 1; j++) {
      if (rows[i][j] === '+' && rows[i][j + 1] === '+' && rows[i + 1][j] === '+' && rows[i + 1][j + 1] === '+') {
        let isValid = true;
        for (let k = i + 2; k < height; k++) {
          if (rows[k][j] !== '+' && rows[k][j + 1] !== '+') {
            isValid = false;
            break;
          }
        }
        for (let k = j + 2; k < width; k++) {
          if (rows[i][k] !== '+' && rows[i + 1][k] !== '+') {
            isValid = false;
            break;
          }
        }
        if (isValid) {
          count++;
        }
      }
    }
  }

  return count;
}

