// @openarc:begin variableLengthQuantity.decode
export const decode: DecodeFn = (bytes) => {
  const result: number[] = [];
  let current = 0;
  for (const byte of bytes) {
    current = (current << 7) | (byte & 0x7F);
    if ((byte & 0x80) === 0) {
      result.push(current);
      current = 0;
    }
  }
  return result;
};
// @openarc:end variableLengthQuantity.decode

export function encode(numbers: number[]): number[] {
  const encoded: number[] = [];
  for (const num of numbers) {
    if (num < 0 || num > 0xFFFFFFFF) {
      throw new Error("Number out of range for 32-bit unsigned integer");
    }
    let remaining = num;
    let first = true;
    while (remaining > 0) {
      const byte = remaining & 0x7F;
      remaining >>= 7;
      if (!first) {
        byte |= 0x80;
      }
      encoded.push(byte);
      first = false;
    }
  }
  return encoded;
}

export function decode(bytes: number[]): number[] {
  const decoded: number[] = [];
  let num = 0;
  for (const byte of bytes) {
    num = (num << 7) | (byte & 0x7F);
    if ((byte & 0x80) === 0) {
      decoded.push(num);
      num = 0;
    }
  }
  return decoded;
}

